#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 1000000

// Structure to hold a run-length encoded pair
typedef struct {
    char letter;
    int count;
} RLEPair;

// Parse RLE string into array of pairs
int parseRLE(const char *s, RLEPair *pairs) {
    int n = 0;
    int i = 0;
    while (s[i] != '$') {
        pairs[n].letter = s[i++];
        // Read the count (may be multiple digits)
        int count = 0;
        while (s[i] >= '0' && s[i] <= '9') {
            count = count * 10 + (s[i] - '0');
            i++;
        }
        pairs[n].count = count;
        n++;
    }
    return n;
}

// Decompress RLE to full string (only for small test cases or debugging)
// Not used in final solution due to memory constraints

// Write RLE pairs to output
void writeRLE(RLEPair *pairs, int n) {
    for (int i = 0; i < n; i++) {
        printf("%c%d", pairs[i].letter, pairs[i].count);
    }
    printf("$\n");
}

// Convert RLE pairs to a temporary string (used for matching)
// Returns length of the string
int pairsToString(RLEPair *pairs, int n, char *str) {
    int pos = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < pairs[i].count; j++) {
            str[pos++] = pairs[i].letter;
        }
    }
    str[pos] = '\0';
    return pos;
}

// Find first occurrence of pattern B in text A (both as RLE pairs)
// Returns index in A where match starts, or -1 if not found
int findFirstOccurrence(RLEPair *A, int nA, RLEPair *B, int nB) {
    // Convert B to string for easier matching
    char *bStr = (char*)malloc(MAX_LEN + 1);
    int bLen = pairsToString(B, nB, bStr);

    // Sliding window over A
    char *aStr = (char*)malloc(MAX_LEN + 1);
    int aLen = pairsToString(A, nA, aStr);

    // Find first occurrence using strstr
    char *found = strstr(aStr, bStr);
    int result = -1;
    if (found != NULL) {
        result = (int)(found - aStr);
    }

    free(bStr);
    free(aStr);
    return result;
}

// Build result RLE from parts
// A[0..endA-1] + C[0..nC-1] + A[startB+lenB .. nA-1]
void buildResult(RLEPair *A, int nA, RLEPair *C, int nC, 
                 int startPos, int lenB, RLEPair *result, int *nResult) {
    // First, we need to convert A to string to know exact positions
    char *aStr = (char*)malloc(MAX_LEN + 1);
    int aLen = pairsToString(A, nA, aStr);

    char *cStr = (char*)malloc(MAX_LEN + 1);
    int cLen = pairsToString(C, nC, cStr);

    // Build result string
    char *resStr = (char*)malloc(MAX_LEN * 2 + 1);
    int resPos = 0;

    // Copy part before match
    for (int i = 0; i < startPos; i++) {
        resStr[resPos++] = aStr[i];
    }
    // Copy C
    for (int i = 0; i < cLen; i++) {
        resStr[resPos++] = cStr[i];
    }
    // Copy part after match
    for (int i = startPos + lenB; i < aLen; i++) {
        resStr[resPos++] = aStr[i];
    }
    resStr[resPos] = '\0';

    // Now compress result string into RLE
    int r = 0;
    char cur = resStr[0];
    int cnt = 1;
    for (int i = 1; i < resPos; i++) {
        if (resStr[i] == cur) {
            cnt++;
        } else {
            result[r].letter = cur;
            result[r].count = cnt;
            r++;
            cur = resStr[i];
            cnt = 1;
        }
    }
    result[r].letter = cur;
    result[r].count = cnt;
    r++;
    *nResult = r;

    free(aStr);
    free(cStr);
    free(resStr);
}

int main() {
    char inputA[MAX_LEN + 1], inputB[MAX_LEN + 1], inputC[MAX_LEN + 1];

    // Read three lines
    fgets(inputA, MAX_LEN + 1, stdin);
    fgets(inputB, MAX_LEN + 1, stdin);
    fgets(inputC, MAX_LEN + 1, stdin);

    // Remove newline if present
    inputA[strcspn(inputA, "\n")] = '\0';
    inputB[strcspn(inputB, "\n")] = '\0';
    inputC[strcspn(inputC, "\n")] = '\0';

    // Parse RLE strings
    RLEPair A[MAX_LEN], B[MAX_LEN], C[MAX_LEN];
    int nA = parseRLE(inputA, A);
    int nB = parseRLE(inputB, B);
    int nC = parseRLE(inputC, C);

    // Find first occurrence of B in A
    int startPos = findFirstOccurrence(A, nA, B, nB);

    if (startPos == -1) {
        // No match, output original A
        writeRLE(A, nA);
        return 0;
    }

    // Calculate length of B in characters
    char *bStr = (char*)malloc(MAX_LEN + 1);
    int lenB = pairsToString(B, nB, bStr);
    free(bStr);

    // Build result
    RLEPair result[MAX_LEN * 2];
    int nResult;
    buildResult(A, nA, C, nC, startPos, lenB, result, &nResult);

    writeRLE(result, nResult);

    return 0;
}

