typedef long long ll;

typedef struct {
    char ch;
    ll len;
} Run;

typedef struct {
    Run *a;
    int n, cap;
} Vec;

static void vec_init(Vec *v) {
    v->a = NULL;
    v->n = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, char ch, ll len) {
    if (len <= 0) return;
    if (v->n > 0 && v->a[v->n - 1].ch == ch) {
        v->a[v->n - 1].len += len;
        return;
    }
    if (v->n == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 8;
        v->a = (Run *)realloc(v->a, sizeof(Run) * v->cap);
    }
    v->a[v->n].ch = ch;
    v->a[v->n].len = len;
    v->n++;
}

static Vec read_rle(void) {
    Vec v;
    vec_init(&v);
    int c;
    while ((c = getchar()) != EOF) {
        if (isspace(c)) continue;
        if (c == '$') break;
        char ch = (char)c;
        ll num = 0;
        while ((c = getchar()) != EOF && isdigit(c)) {
            num = num * 10 + (c - '0');
        }
        vec_push(&v, ch, num);
        if (c == '$') break;
        while (c != EOF && isspace(c)) c = getchar();
        if (c == '$') break;
        if (c != EOF) ungetc(c, stdin);
    }
    return v;
}

static ll total_len(const Vec *v) {
    ll s = 0;
    for (int i = 0; i < v->n; i++) s += v->a[i].len;
    return s;
}

static char get_char_at(const Vec *v, int *idx, ll *off, ll pos) {
    while (*idx < v->n) {
        ll rem = v->a[*idx].len - *off;
        if (pos < rem) {
            *off += pos;
            return v->a[*idx].ch;
        }
        pos -= rem;
        (*idx)++;
        *off = 0;
    }
    return 0;
}

static int match_at(const Vec *A, ll start, const Vec *B) {
    int ia = 0, ib = 0;
    ll oa = 0, ob = 0;

    /* move A cursor to start */
    ll p = start;
    while (ia < A->n) {
        ll rem = A->a[ia].len - oa;
        if (p < rem) {
            oa += p;
            break;
        }
        p -= rem;
        ia++;
        oa = 0;
    }
    if (p != 0 || ia > A->n) return 0;

    while (ib < B->n) {
        if (ia >= A->n) return 0;
        if (A->a[ia].ch != B->a[ib].ch) return 0;
        ll ra = A->a[ia].len - oa;
        ll rb = B->a[ib].len - ob;
        ll take = ra < rb ? ra : rb;
        oa += take;
        ob += take;
        if (oa == A->a[ia].len) {
            ia++;
            oa = 0;
        }
        if (ob == B->a[ib].len) {
            ib++;
            ob = 0;
        }
    }
    return 1;
}

static ll find_first(const Vec *A, const Vec *B) {
    ll la = total_len(A);
    ll lb = total_len(B);
    if (lb > la) return -1;
    if (lb == 0) return 0;
    for (ll s = 0; s + lb <= la; s++) {
        if (match_at(A, s, B)) return s;
    }
    return -1;
}

static void append_range(Vec *out, const Vec *src, ll l, ll r) {
    if (l >= r) return;
    ll pos = 0;
    for (int i = 0; i < src->n; i++) {
        ll nl = pos;
        ll nr = pos + src->a[i].len;
        ll L = l > nl ? l : nl;
        ll R = r < nr ? r : nr;
        if (L < R) vec_push(out, src->a[i].ch, R - L);
        pos = nr;
        if (pos >= r) break;
    }
}

int main(void) {
    Vec A = read_rle();
    Vec B = read_rle();
    Vec C = read_rle();

    ll pos = find_first(&A, &B);
    ll lenA = total_len(&A);
    ll lenB = total_len(&B);

    Vec out;
    vec_init(&out);

    if (pos < 0) {
        append_range(&out, &A, 0, lenA);
    } else {
        append_range(&out, &A, 0, pos);
        for (int i = 0; i < C.n; i++) vec_push(&out, C.a[i].ch, C.a[i].len);
        append_range(&out, &A, pos + lenB, lenA);
    }

    for (int i = 0; i < out.n; i++) {
        printf("%c%lld", out.a[i].ch, out.a[i].len);
    }
    printf("$\n");

    free(A.a);
    free(B.a);
    free(C.a);
    free(out.a);
    return 0;
}

