        if (s[i] == '$') break;
        char c = s[i];
        i++;
        int num = 0;
        while (i < (int)s.size() && isdigit(s[i])) {
            num = num * 10 + (s[i] - '0');
            i++;
        }
        res.append(num, c);
    }
    return res;
}

