string encode(const string &s) {
    string res;
    int n = s.size();
    int i = 0;
    while (i < n) {
        char c = s[i];
        int cnt = 0;
        while (i < n && s[i] == c) {
            cnt++;
            i++;
        }
        res.push_back(c);
        res += to_string(cnt);
    }
    res.push_back('$');
    return res;
}

