};

vector<Run> readRLE() {
    vector<Run> v;
    while (true) {
        string s;
        cin >> s;
        if (s == "$") break;
        char c = s[0];
        int64 x;
        cin >> x;
        if (!v.empty() && v.back().ch == c) v.back().len += x;
        else v.push_back({c, x});
    }
    return v;
}

vector<Run> mergeRuns(const vector<Run>& a) {
    vector<Run> res;
    for (auto &r : a) {
        if (r.len == 0) continue;
        if (!res.empty() && res.back().ch == r.ch) res.back().len += r.len;
        else res.push_back(r);
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Run> A = readRLE();
    vector<Run> B = readRLE();
    vector<Run> C = readRLE();

    // Empty B is not expected in normal input, but handle safely.
    if (B.empty()) {
        vector<Run> ans = A;
        ans.insert(ans.begin(), C.begin(), C.end());
        ans = mergeRuns(ans);
        for (auto &r : ans) cout << r.ch << ' ' << r.len << '\n';
        cout << "$\n";
        return 0;
    }

    int n = (int)A.size();
    int m = (int)B.size();

    int foundL = -1, foundR = -1; // matched A runs [foundL..foundR]
    int64 leftCut = 0, rightCut = 0; // lengths consumed in boundary runs

    // Find first occurrence of B in A.
    // Since both are RLE, any match aligns with runs:
    // - if m == 1: match inside one run of A
    // - if m >= 2: first and last B runs may be partial inside A runs,
    //   middle B runs must match whole A runs exactly.
    if (m == 1) {
        for (int i = 0; i < n; i++) {
            if (A[i].ch == B[0].ch && A[i].len >= B[0].len) {
                foundL = foundR = i;
                leftCut = B[0].len;
                rightCut = 0;
                break;
            }
        }
    } else {
        for (int i = 0; i < n; i++) {
            if (A[i].ch != B[0].ch || A[i].len < B[0].len) continue;

            int j = i + 1;
            bool ok = true;

            for (int k = 1; k <= m - 2; k++) {
                if (j >= n || A[j].ch != B[k].ch || A[j].len != B[k].len) {
                    ok = false;
                    break;
                }
                j++;
            }
            if (!ok) continue;
            if (j >= n) continue;
            if (A[j].ch != B[m - 1].ch || A[j].len < B[m - 1].len) continue;

            foundL = i;
            foundR = j;
            leftCut = B[0].len;
            rightCut = B[m - 1].len;
            break;
        }
    }

    vector<Run> ans;

    if (foundL == -1) {
        ans = A;
    } else {
        // Prefix before match
        for (int i = 0; i < foundL; i++) ans.push_back(A[i]);

        // Remaining left part of first matched run
        if (m == 1) {
            if (A[foundL].len > B[0].len) {
                ans.push_back({A[foundL].ch, A[foundL].len - B[0].len});
            }
        } else {
            if (A[foundL].len > leftCut) {
                ans.push_back({A[foundL].ch, A[foundL].len - leftCut});
            }
        }

        // Insert C
        for (auto &r : C) ans.push_back(r);

        // Remaining right part of last matched run
        if (m >= 2) {
            if (A[foundR].len > rightCut) {
                ans.push_back({A[foundR].ch, A[foundR].len - rightCut});
            }
        }

        // Suffix after match
        for (int i = foundR + 1; i < n; i++) ans.push_back(A[i]);

        ans = mergeRuns(ans);
    }

    for (auto &r : ans) {
        cout << r.ch << ' ' << r.len << '\n';
    }
    cout << "$\n";

    return 0;
}

