import sys


def read_tokens():
    return sys.stdin.read().split()


def parse_rle(s):
    # s: like A12B3$
    runs = []
    i = 0
    n = len(s)
    while i < n and s[i] != '$':
        ch = s[i]
        i += 1
        j = i
        while j < n and s[j].isdigit():
            j += 1
        runs.append((ch, int(s[i:j])))
        i = j
    return runs


def merge_runs(runs):
    if not runs:
        return []
    res = []
    for ch, cnt in runs:
        if cnt == 0:
            continue
        if res and res[-1][0] == ch:
            res[-1] = (ch, res[-1][1] + cnt)
        else:
            res.append((ch, cnt))
    return res


def char_at(runs, pos):
    # 0-indexed position in expanded string
    acc = 0
    for ch, cnt in runs:
        if pos < acc + cnt:
            return ch
        acc += cnt
    return None


def substring_equal(a_runs, start, b_runs, b_len):
    # compare expanded A[start:start+b_len] with expanded B
    i = 0  # index in a_runs
    offset_a = start
    acc = 0
    while i < len(a_runs) and offset_a >= acc + a_runs[i][1]:
        acc += a_runs[i][1]
        i += 1
    if i == len(a_runs):
        return False

    j = 0  # index in b_runs
    off_in_a = offset_a - acc
    off_in_b = 0

    while j < len(b_runs):
        if i >= len(a_runs):
            return False
        cha, lena = a_runs[i]
        chb, lenb = b_runs[j]
        if cha != chb:
            return False
        take = min(lena - off_in_a, lenb - off_in_b)
        off_in_a += take
        off_in_b += take
        if off_in_a == lena:
            i += 1
            off_in_a = 0
        if off_in_b == lenb:
            j += 1
            off_in_b = 0
    return True


def find_first_occurrence(a_runs, b_runs):
    len_a = sum(cnt for _, cnt in a_runs)
    len_b = sum(cnt for _, cnt in b_runs)
    if len_b == 0:
        return 0
    if len_b > len_a:
        return -1

    first_b = b_runs[0][0]
    pos = 0
    for ch, cnt in a_runs:
        if ch == first_b:
            for k in range(cnt):
                start = pos + k
                if start + len_b > len_a:
                    return -1
                if substring_equal(a_runs, start, b_runs, len_b):
                    return start
        pos += cnt
    return -1


def slice_runs(runs, l, r):
    # expanded substring [l, r)
    if l >= r:
        return []
    res = []
    pos = 0
    for ch, cnt in runs:
        nl = max(l, pos)
        nr = min(r, pos + cnt)
        if nl < nr:
            res.append((ch, nr - nl))
        pos += cnt
        if pos >= r:
            break
    return res


def encode_runs(runs):
    runs = merge_runs(runs)
    return ''.join(f"{ch}{cnt}" for ch, cnt in runs) + '$'


def main():
    tokens = read_tokens()
    if len(tokens) < 3:
        return
    A = parse_rle(tokens[0])
    B = parse_rle(tokens[1])
    C = parse_rle(tokens[2])

