import java.io.*;
import java.util.*;

public class Main {
    // Store one RLE run
    static class Run {
        char ch;
        long len;
        Run(char ch, long len) {
            this.ch = ch;
            this.len = len;
        }
    }

    // KMP state node on run-level pattern
    static class State {
        int matchedRuns;      // number of fully matched pattern runs from the beginning
        long matchedInRun;    // matched length in the next pattern run (0 if exactly at boundary)
        State(int matchedRuns, long matchedInRun) {
            this.matchedRuns = matchedRuns;
            this.matchedInRun = matchedInRun;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String nextToken() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (Character.isWhitespace(c));
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char)c);
                c = read();
            }
            return sb.toString();
        }
    }

    static List<Run> parseRLE(String s) {
        List<Run> runs = new ArrayList<>();
        int i = 0, n = s.length();
        while (i < n && s.charAt(i) != '$') {
            char ch = s.charAt(i++);
            long num = 0;
            while (i < n && Character.isDigit(s.charAt(i))) {
                num = num * 10 + (s.charAt(i) - '0');
                i++;
            }
            if (num > 0) {
                if (!runs.isEmpty() && runs.get(runs.size() - 1).ch == ch) {
                    runs.get(runs.size() - 1).len += num;
                } else {
                    runs.add(new Run(ch, num));
                }
            }
        }
        return runs;
    }

    static void appendRun(List<Run> out, char ch, long len) {
        if (len <= 0) return;
        if (!out.isEmpty() && out.get(out.size() - 1).ch == ch) {
            out.get(out.size() - 1).len += len;
        } else {
            out.add(new Run(ch, len));
        }
    }

    static String encodeRLE(List<Run> runs) {
        StringBuilder sb = new StringBuilder();
        for (Run r : runs) {
            sb.append(r.ch).append(r.len);
        }
        sb.append('$');
        return sb.toString();
    }

    static boolean stateEquals(State a, State b) {
        return a.matchedRuns == b.matchedRuns && a.matchedInRun == b.matchedInRun;
    }

    // Advance automaton by consuming x copies of character ch.
    // Pattern is in runs P.
    static State advance(State st, char ch, long x, List<Run> P) {
        int m = P.size();
        int i = st.matchedRuns;
        long off = st.matchedInRun;

        while (x > 0) {
            if (i == m) {
                // already fully matched; caller should stop before this normally
                break;
            }

            Run pr = P.get(i);
            if (pr.ch != ch) {
                // mismatch after partial progress inside current run cannot be repaired here;
                // caller uses KMP fallback before calling this transition.
                return null;
            }

            long need = pr.len - off;
            if (x < need) {
                off += x;
                x = 0;
            } else {
                x -= need;
                i++;
                off = 0;
            }
        }
        return new State(i, off);
    }

    // Build prefix function on pattern runs
    static int[] buildPi(List<Run> P) {
        int m = P.size();
        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && !sameRun(P.get(i), P.get(j))) j = pi[j - 1];
            if (sameRun(P.get(i), P.get(j))) j++;
            pi[i] = j;
        }
        return pi;
    }

    static boolean sameRun(Run a, Run b) {
        return a.ch == b.ch && a.len == b.len;
    }

    // Find first occurrence of pattern B in text A, both as expanded strings but represented by runs.
    // Returns {startPos, endPosExclusive}; {-1,-1} if not found.
    //
    // This implementation uses a run-aware search:
    // 1) Handle single-run pattern directly.
    // 2) For multi-run pattern, search middle runs with KMP over runs (exact run equality),
    //    then verify first/last runs with >= conditions.
    static long[] findFirstOccurrence(List<Run> A, List<Run> B) {
        int n = A.size(), m = B.size();
        if (m == 0) return new long[]{0, 0};

        long[] pos = new long[n + 1];
        for (int i = 0; i < n; i++) pos[i + 1] = pos[i] + A.get(i).len;

        if (m == 1) {
            char c = B.get(0).ch;
            long need = B.get(0).len;
            for (int i = 0; i < n; i++) {
                if (A.get(i).ch == c && A.get(i).len >= need) {
                    return new long[]{pos[i], pos[i] + need};
                }
            }
            return new long[]{-1, -1};
        }

        if (m == 2) {
            for (int i = 0; i + 1 < n; i++) {
                if (A.get(i).ch == B.get(0).ch && A.get(i).len >= B.get(0).len &&
                    A.get(i + 1).ch == B.get(1).ch && A.get(i + 1).len >= B.get(1).len) {
                    long start = pos[i] + (A.get(i).len - B.get(0).len);
                    // earliest occurrence starts at beginning of matched suffix in run i
                    start = pos[i] + (A.get(i).len >= B.get(0).len ? 0 : 0);
                    // Actually with two runs, match must start somewhere inside run i and then continue into run i+1.
                    // Since B's first run is followed by different char (after compression), it must end exactly at end of A[i].
                    // Therefore start is end(A[i]) - B0.len.
                    start = pos[i] + A.get(i).len - B.get(0).len;
                    long end = pos[i + 1] + B.get(1).len;
                    return new long[]{start, end};
                }
            }
            return new long[]{-1, -1};
        }

        // m >= 3
        List<Run> mid = B.subList(1, m - 1);
        int[] pi = buildPi(mid);
        int j = 0;

        for (int i = 0; i < n; i++) {
            while (j > 0 && !sameRun(A.get(i), mid.get(j))) j = pi[j - 1];
            if (sameRun(A.get(i), mid.get(j))) j++;

            if (j == mid.size()) {
                int endMid = i; // A[endMid] matches mid[last]
                int startMid = i - mid.size() + 1; // A[startMid] matches mid[0]
                int left = startMid - 1;
                int right = endMid + 1;

                if (left >= 0 && right < n &&
                    A.get(left).ch == B.get(0).ch && A.get(left).len >= B.get(0).len &&
                    A.get(right).ch == B.get(m - 1).ch && A.get(right).len >= B.get(m - 1).len) {

                    long start = pos[left] + A.get(left).len - B.get(0).len;
                    long end = pos[right] + B.get(m - 1).len;
                    return new long[]{start, end};
                }
                j = pi[j - 1];
            }
        }
        return new long[]{-1, -1};
    }

    static List<Run> replaceFirst(List<Run> A, long l, long r, List<Run> C) {
        List<Run> out = new ArrayList<>();
        long cur = 0;
        for (Run run : A) {
            long runL = cur;
            long runR = cur + run.len;
            if (runR <= l || r <= runL) {
                appendRun(out, run.ch, run.len);
            } else {
                if (runL < l) appendRun(out, run.ch, l - runL);
                if (runR > r) {
                    // suffix part will be appended after C if current run crosses right boundary
                }
            }
            cur = runR;
        }

        // Build properly in one pass around [l, r)
        out.clear();
        cur = 0;
        boolean inserted = false;
        for (Run run : A) {
            long runL = cur;
            long runR = cur + run.len;

            if (runR <= l) {
                appendRun(out, run.ch, run.len);
            } else if (runL >= r) {
                if (!inserted) {
                    for (Run rc : C) appendRun(out, rc.ch, rc.len);
                    inserted = true;
                }
                appendRun(out, run.ch, run.len);
            } else {
                // overlap
                if (runL < l) appendRun(out, run.ch, l - runL);
                if (!inserted) {
                    for (Run rc : C) appendRun(out, rc.ch, rc.len);
                    inserted = true;
                }
                if (runR > r) appendRun(out, run.ch, runR - r);
            }
            cur = runR;
        }
        if (!inserted) {
            for (Run rc : C) appendRun(out, rc.ch, rc.len);
        }
        return out;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String Araw = fs.nextToken();
        String Braw = fs.nextToken();
        String Craw = fs.nextToken();

        List<Run> A = parseRLE(Araw);
        List<Run> B = parseRLE(Braw);
        List<Run> C = parseRLE(Craw);

        long[] occ = findFirstOccurrence(A, B);
        List<Run> ans;
        if (occ[0] == -1) {
            ans = A;
        } else {
            ans = replaceFirst(A, occ[0], occ[1], C);
        }

        System.out.println(encodeRLE(ans));
    }
}
